def _campaign_status_summary():
    """D-080: read the SINGLE authoritative campaign-status source (shared with brain_refresh.py).
    No campaign counts/ids are hardcoded here; a stale divergence between the two generators
    is impossible because both compute from this one file."""
    cs = json.load(open(os.path.join(HERE, "campaign_status_v0_1.json"), encoding="utf-8"))["campaigns"]
    cap = sorted([c for c, v in cs.items() if v.get("class") == "genuine_prospective"])
    exp = sorted([c for c, v in cs.items()
                  if v.get("class") == "genuine_prospective" and v.get("expectancy_eligible")])
    exc = {c: v.get("exclusion_reason", "?") for c, v in cs.items()
           if v.get("class") == "genuine_prospective" and not v.get("expectancy_eligible")}
    return {"capture_count": len(cap), "capture_ids": cap,
            "expectancy_count": len(exp), "expectancy_ids": exp, "excluded": exc,
            "_source": "campaign_status_v0_1.json (D-080 single authority)"}


