def write(name, obj, jsonl=False):
    p = os.path.join(HERE, name)
    with open(p, "w", encoding="utf-8") as f:
        if jsonl:
            for row in obj:
                f.write(json.dumps(row, ensure_ascii=False) + "\n")
        else:
            json.dump(obj, f, indent=1, ensure_ascii=False)
    print("wrote", name)


